def compute(vars):
    television = vars["v1"]
    local_residential_telephone = vars["v2"]
    total_subscribers = television + local_residential_telephone

    return {
        "value": total_subscribers,
        "trace": {
            "television_subscribers": television,
            "local_residential_telephone_subscribers": local_residential_telephone,
            "total_subscribers": total_subscribers,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "subscribers"
            }
        }
    }
